const acorn=require('acorn');
const {JSDOM,VirtualConsole}=require('jsdom');

const repo=process.env.GH_REPOSITORY,token=process.env.GH_TOKEN,path='siza-mobile-test/index.html';
const headers={'Accept':'application/vnd.github+json','Authorization':`Bearer ${token}`,'X-GitHub-Api-Version':'2022-11-28'};
const api=`https://api.github.com/repos/${repo}/contents/${path}`;
const assert=(v,m)=>{if(!v)throw new Error(m)};

async function getFile(p){const r=await fetch(`https://api.github.com/repos/${repo}/contents/${p}?ref=main`,{headers});if(!r.ok)throw new Error(`${p}: GET ${r.status}`);const f=await r.json();return{sha:f.sha,text:Buffer.from(f.content.replace(/\n/g,''),'base64').toString('utf8')}}
function parse(html){const so=html.lastIndexOf('<script>'),sc=html.indexOf('</script>',so);assert(so>=0&&sc>so,'main script not found');const start=so+8,code=html.slice(start,sc),ast=acorn.parse(code,{ecmaVersion:'latest'}),decl=[];function walk(n){if(!n||typeof n!=='object')return;if(n.type==='FunctionDeclaration'&&n.id)decl.push(n);for(const[k,v]of Object.entries(n)){if(k==='start'||k==='end')continue;if(Array.isArray(v))v.forEach(walk);else if(v&&typeof v==='object'&&v.type)walk(v)}}walk(ast);return{start,sc,code,decl}}
function replaceFn(html,name,replacement){const p=parse(html),nodes=p.decl.filter(n=>n.id.name===name);assert(nodes.length===1,`${name}: expected 1, got ${nodes.length}`);const n=nodes[0],code=p.code.slice(0,n.start)+replacement+p.code.slice(n.end);return html.slice(0,p.start)+code+html.slice(p.sc)}
function inlineCore(html,files){let out=html;for(const[name,text]of [['card-effects.js',files.effects],['card-schema.js',files.schema],['cards.js',files.cards],['card-renderer.js',files.renderer]]){const tag=`<script src="../siza-core/${name}"></script>`;if(out.includes(tag))out=out.replace(tag,`<script>${text}</script>`)}return out}
function makeDom(html,label){const vc=new VirtualConsole();vc.on('jsdomError',e=>console.error(`[JSDOM ${label}]`,e.message));return new JSDOM(html,{runScripts:'dangerously',url:'https://siza.local/siza-mobile-test/',virtualConsole:vc})}

const declarePlayerCombat=[
"function attackDeclaredDamageV1(P,indices){let amount=0,sources=[];for(const i of indices){const c=cardById(P.battlefield[i]);for(const effect of SizaCardEffects.forEvent(c,'attack-declared'))if(effect.type==='damage-character'&&(effect.target||'opponent')==='opponent'&&effect.amount>0){amount+=effect.amount;sources.push(c.name)}}return{amount,source:sources.length&&sources.every(x=>x===sources[0])?sources[0]:'Efectos de ataque'}}",
"function combatPowerCounterGainV1(c){return SizaCardEffects.forEvent(c,'combat-damage').filter(e=>e.type==='add-power-counter').reduce((n,e)=>n+(e.amount||0),0)}",
"function declarePlayerCombat(indices){const M=state.match,P=M.player;indices=indices.filter(i=>canAttackV070(P,i));if(!indices.length||P.combatUsed)return;P.combatUsed=true;P.exhausted=[...new Set([...P.exhausted,...indices])];M.ui.attackMode=false;M.ui.attackers=[];const trigger=attackDeclaredDamageV1(P,indices),bonus=trigger.amount;if(bonus){M.enemy.life-=bonus;setDamageFx('enemy',bonus,trigger.source||'Efecto de ataque','Personaje rival');addLog(trigger.source==='Contrabandista Carmesí'?'Contrabandista':'Ataque',bonus+' daño al declarar ataque.');checkWin();if(M.over)return render()}M.combat={owner:'player',attackers:indices.map(index=>({index,id:P.battlefield[index]})),blockers:{}};M.active='enemy-defense';M.phase='Defensa rival';assignAiBlockersV600();render();setTimeout(()=>M.combat&&resolveCombatV600(),1300)}"
].join('\n');

const resolveCombat="function resolveCombatV600(){const M=state.match,C=M.combat,A=M[C.owner],D=C.owner==='player'?M.enemy:M.player,ad=new Set,dd=new Set,ai=new Map,di=new Map;let damage=0;for(let s=0;s<C.attackers.length;s++){const a=C.attackers[s],ac=cardById(A.battlefield[a.index]),ap=effectivePower(A,a.index),at=toughV070(A,a.index),bi=C.blockers[String(s)],bc=bi==null?null:cardById(D.battlefield[bi]);if(bc){const bp=effectivePower(D,bi),bt=toughV070(D,bi);if(ap>=bt)dd.add(bi);if(bp>=at)ad.add(a.index);const ag=ap>0?combatPowerCounterGainV1(ac):0,bg=bp>0?combatPowerCounterGainV1(bc):0;if(ag)ai.set(a.index,(ai.get(a.index)||0)+ag);if(bg)di.set(bi,(di.get(bi)||0)+bg);addLog('Daño simultáneo',ac.name+' '+ap+'/'+at+' ↔ '+bc.name+' '+bp+'/'+bt+'.')}else{damage+=ap;const ag=ap>0?combatPowerCounterGainV1(ac):0;if(ag)ai.set(a.index,(ai.get(a.index)||0)+ag)}}if(damage){D.life-=damage;addLog('Daño de combate',damage+' daño al Personaje.')}for(const[i,gain]of ai)if(!ad.has(i))A.powerCounters[i]=(A.powerCounters[i]||0)+gain;for(const[i,gain]of di)if(!dd.has(i))D.powerCounters[i]=(D.powerCounters[i]||0)+gain;[...dd].sort((a,b)=>b-a).forEach(i=>removeBattlefieldAt(D,i));[...ad].sort((a,b)=>b-a).forEach(i=>removeBattlefieldAt(A,i));M.combat=null;checkWin();if(!M.over&&C.owner==='player'){M.active='player';M.phase='Main'}else if(!M.over){M.active='enemy';setTimeout(finishEnemyTurn,500)}save();render()}";

const enemyAfterMain="function enemyAfterMain(){const M=state.match,E=M.enemy;const attackers=E.battlefield.map((_,i)=>canAttackV070(E,i)?{index:i,id:E.battlefield[i]}:null).filter(Boolean);if(!attackers.length)return setTimeout(finishEnemyTurn,400);E.exhausted=[...new Set([...E.exhausted,...attackers.map(a=>a.index)])];const trigger=attackDeclaredDamageV1(E,attackers.map(a=>a.index)),bonus=trigger.amount;if(bonus){M.player.life-=bonus;setDamageFx('player',bonus,trigger.source||'Efecto de ataque',state.player.mag.name);addLog(trigger.source==='Contrabandista Carmesí'?'Contrabandista rival':'Ataque rival',bonus+' daño al declarar ataque.');checkWin();if(M.over)return render()}M.combat={owner:'enemy',attackers,blockers:{}};M.active='defense';M.phase='Tu Defensa';render()}";

(async()=>{
 const index=await getFile(path),files={effects:(await getFile('siza-core/card-effects.js')).text,schema:(await getFile('siza-core/card-schema.js')).text,cards:(await getFile('siza-core/cards.js')).text,renderer:(await getFile('siza-core/card-renderer.js')).text};let html=index.text;console.log('Current Mobile blob '+index.sha);
 const marker='window.SIZA={';assert(html.includes(marker),'SIZA export marker missing');
 const oldSource=inlineCore(html,files),oldProbe="window.__COMBAT_FX_TEST__={createMatch,setMatch:m=>state.match=m,addCreatureV070,declarePlayerCombat,resolveCombatV600,enemyAfterMain,TEST_CARD_DB_V1};\n",oldDom=makeDom(oldSource.replace(marker,oldProbe+marker),'old');oldDom.window.setTimeout=()=>0;
 html=replaceFn(html,'declarePlayerCombat',declarePlayerCombat);html=replaceFn(html,'resolveCombatV600',resolveCombat);html=replaceFn(html,'enemyAfterMain',enemyAfterMain);
 const p=parse(html);for(const name of ['declarePlayerCombat','resolveCombatV600','enemyAfterMain']){const n=p.decl.find(x=>x.id.name===name);assert(n,`${name} missing`);const src=p.code.slice(n.start,n.end);assert(!src.includes("==='smuggler'")&&!src.includes("==='ignimite'"),`${name} still hardcodes migrated combat cards`)}
 const newSource=inlineCore(html,files),newProbe="window.__COMBAT_FX_TEST__={createMatch,setMatch:m=>state.match=m,addCreatureV070,declarePlayerCombat,resolveCombatV600,enemyAfterMain,TEST_CARD_DB_V1,attackDeclaredDamageV1,combatPowerCounterGainV1};\n",newDom=makeDom(newSource.replace(marker,newProbe+marker),'new');newDom.window.setTimeout=()=>0;
 function base(dom){const H=dom.window.__COMBAT_FX_TEST__,M=H.createMatch(false,'immediate');H.setMatch(M);for(const P of[M.player,M.enemy]){P.hand=[];P.library=[];P.graveyard=[];P.battlefield=[];P.artifacts=[];P.equipment=[];P.powerCounters=[];P.summonedOn=[];P.exhausted=[];P.combatUsed=false}M.player.life=20;M.enemy.life=20;M.combat=null;M.active='player';return{H,M}}
 function snap(M){return JSON.stringify({pl:M.player.life,el:M.enemy.life,pbf:M.player.battlefield,ebf:M.enemy.battlefield,pc:M.player.powerCounters,ec:M.enemy.powerCounters,pe:M.player.exhausted,ee:M.enemy.exhausted,pcu:M.player.combatUsed,ecu:M.enemy.combatUsed,active:M.active,combat:M.combat?{owner:M.combat.owner,attackers:M.combat.attackers,blockers:M.combat.blockers}:null})}
 function compare(name,setup,act){const a=base(oldDom),b=base(newDom);setup(a.H,a.M);setup(b.H,b.M);act(a.H,a.M);act(b.H,b.M);const sa=snap(a.M),sb=snap(b.M);assert(sa===sb,name+' mismatch\nOLD '+sa+'\nNEW '+sb);console.log('PASS equivalence '+name)}
 compare('smuggler player declaration',(H,M)=>H.addCreatureV070(M.player,'smuggler'),(H,M)=>H.declarePlayerCombat([0]));
 compare('smuggler enemy declaration',(H,M)=>{M.active='enemy';H.addCreatureV070(M.enemy,'smuggler')},(H,M)=>H.enemyAfterMain());
 compare('ignimite unblocked combat',(H,M)=>{H.addCreatureV070(M.player,'ignimite');M.combat={owner:'player',attackers:[{index:0,id:'ignimite'}],blockers:{}};M.active='enemy-defense'},(H,M)=>H.resolveCombatV600());
 const H=newDom.window.__COMBAT_FX_TEST__;
 H.TEST_CARD_DB_V1.push({id:'generated_attack_ping',name:'Generated Attack Ping',type:'Creature',cost:1,difficulty:1,pips:{},power:2,toughness:2,text:'Attack ping.',art:'multi',glyph:'A',effects:[{event:'attack-declared',type:'damage-character',target:'opponent',amount:2}]});let M=H.createMatch(false,'immediate');H.setMatch(M);for(const P of[M.player,M.enemy]){P.battlefield=[];P.powerCounters=[];P.summonedOn=[];P.exhausted=[];P.combatUsed=false}H.addCreatureV070(M.player,'generated_attack_ping');M.enemy.life=20;H.declarePlayerCombat([0]);assert(M.enemy.life===18,'Generated attack-declared damage did not execute');console.log('PASS generated attack-declared damage 2');
 H.TEST_CARD_DB_V1.push({id:'generated_grower',name:'Generated Grower',type:'Creature',cost:1,difficulty:1,pips:{},power:1,toughness:3,text:'Grow.',art:'multi',glyph:'G',effects:[{event:'combat-damage',type:'add-power-counter',amount:2}]});M=H.createMatch(false,'immediate');H.setMatch(M);for(const P of[M.player,M.enemy]){P.battlefield=[];P.powerCounters=[];P.summonedOn=[];P.exhausted=[]}H.addCreatureV070(M.player,'generated_grower');M.combat={owner:'player',attackers:[{index:0,id:'generated_grower'}],blockers:{}};M.active='enemy-defense';H.resolveCombatV600();assert(M.player.powerCounters[0]===2,'Generated combat counter effect did not execute amount 2');console.log('PASS generated combat-damage counter +2');
 const core=newDom.window.SIZA.runArenaCriticalV071();assert(core.passed===core.total,'Arena '+core.passed+'/'+core.total);console.log('PASS Arena '+core.passed+'/'+core.total);oldDom.window.close();newDom.window.close();
 const w=await fetch(api,{method:'PUT',headers:{...headers,'Content-Type':'application/json'},body:JSON.stringify({message:'Resolve combat triggers from structured card data',content:Buffer.from(html,'utf8').toString('base64'),sha:index.sha,branch:'main'})});if(!w.ok)throw new Error(`PUT ${w.status}: ${await w.text()}`);const out=await w.json();console.log('COMMIT '+out.commit.sha);
})().catch(e=>{console.error(e.stack||e.message);process.exit(1)});
